import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class TriesTour {
    static class Node {
        Map<Character, Node> children = new TreeMap<>();   // TreeMap: children in alphabetical order
        boolean isWord;
    }

    static Node root = new Node();

    static void insert(String word) {
        Node n = root;
        for (char c : word.toCharArray()) n = n.children.computeIfAbsent(c, k -> new Node());
        n.isWord = true;
    }

    static Node find(String prefix) {
        Node n = root;
        for (char c : prefix.toCharArray()) {
            n = n.children.get(c);
            if (n == null) return null;
        }
        return n;
    }

    static void collect(Node n, StringBuilder path, List<String> out) {
        if (n.isWord) out.add(path.toString());
        for (Map.Entry<Character, Node> e : n.children.entrySet()) {
            path.append(e.getKey());
            collect(e.getValue(), path, out);
            path.deleteCharAt(path.length() - 1);
        }
    }

    public static void main(String[] args) {
        for (String w : new String[]{"car", "card", "care", "cart", "cat", "dog", "do"}) insert(w);
        System.out.println("search(car) = " + (find("car") != null && find("car").isWord));
        System.out.println("search(ca)  = " + (find("ca") != null && find("ca").isWord) + " (only a prefix)");
        for (String prefix : new String[]{"car", "do", "x"}) {
            List<String> words = new ArrayList<>();
            Node start = find(prefix);
            if (start != null) collect(start, new StringBuilder(prefix), words);
            System.out.println("complete \"" + prefix + "\": " + words);
        }
    }
}

