public class TrieConstruction {
    static class Node {
        Node[] children = new Node[26];       // index c - 'a'
        boolean isWord;
    }

    static Node root = new Node();
    static int totalNodes = 1;                // the root

    static int insert(String word) {
        Node n = root;
        int created = 0;
        for (char c : word.toCharArray()) {
            int i = c - 'a';
            if (n.children[i] == null) {      // only the new part of the word costs nodes
                n.children[i] = new Node();
                created++;
            }
            n = n.children[i];
        }
        n.isWord = true;                      // mark the end of a whole word
        totalNodes += created;
        return created;
    }

    static void print(Node n, int depth) {
        for (int i = 0; i < 26; i++) {
            Node child = n.children[i];
            if (child == null) continue;
            System.out.println("  ".repeat(depth + 1) + (char) ('a' + i) + (child.isWord ? "*" : ""));
            print(child, depth + 1);
        }
    }

    public static void main(String[] args) {
        int letters = 0;
        for (String w : new String[]{"tea", "ten", "tent", "to", "inn", "in"}) {
            letters += w.length();
            System.out.println("insert " + w + ": " + insert(w) + " new node(s)");
        }
        System.out.println(totalNodes + " nodes (including the root) for " + letters + " letters");
        System.out.println("root");
        print(root, 0);
    }
}

import java.util.HashMap;
import java.util.Map;

public class TrieInsertSearchDelete {
    static class Node {
        Map<Character, Node> children = new HashMap<>();
        boolean isWord;
    }

    static Node root = new Node();

    static void insert(String word) {
        Node n = root;
        for (char c : word.toCharArray()) n = n.children.computeIfAbsent(c, k -> new Node());
        n.isWord = true;
    }

    static boolean search(String word) {
        Node n = root;
        for (char c : word.toCharArray()) {
            n = n.children.get(c);
            if (n == null) return false;          // fell off the tree
        }
        return n.isWord;                          // a prefix alone is not enough
    }

    static boolean delete(String word) { return delete(root, word, 0); }

    // Returns true if the word was stored (and is now removed)
    static boolean delete(Node n, String word, int i) {
        if (i == word.length()) {
            if (!n.isWord) return false;
            n.isWord = false;
            return true;
        }
        char c = word.charAt(i);
        Node child = n.children.get(c);
        if (child == null) return false;
        boolean removed = delete(child, word, i + 1);
        if (removed && !child.isWord && child.children.isEmpty()) {
            n.children.remove(c);                 // prune a node nobody needs any more
        }
        return removed;
    }

    static int countNodes(Node n) {
        int total = 1;
        for (Node child : n.children.values()) total += countNodes(child);
        return total;
    }

    public static void main(String[] args) {
        for (String w : new String[]{"app", "apple", "apply", "bat"}) insert(w);
        System.out.println("nodes: " + countNodes(root));
        for (String w : new String[]{"app", "ap", "apt", "apple"}) System.out.println("search(" + w + ") = " + search(w));
        for (String w : new String[]{"apple", "app", "bat", "cat"}) {
            boolean removed = delete(w);
            System.out.println("delete(" + w + ") = " + removed + ", nodes now " + countNodes(root)
                    + ", search(app) = " + search("app") + ", search(apply) = " + search("apply"));
        }
    }
}

