import java.util.Map;
import java.util.TreeMap;

public class PrefixMatching {
    static class Node {
        Map<Character, Node> children = new TreeMap<>();
        int passCount;                          // words whose path goes through this node
        boolean isWord;
    }

    static Node root = new Node();

    static void insert(String word) {
        Node n = root;
        for (char c : word.toCharArray()) {
            n = n.children.computeIfAbsent(c, k -> new Node());
            n.passCount++;
        }
        n.isWord = true;
    }

    static Node walk(String prefix) {
        Node n = root;
        for (char c : prefix.toCharArray()) {
            n = n.children.get(c);
            if (n == null) return null;
        }
        return n;
    }

    static boolean startsWith(String prefix) { return walk(prefix) != null; }

    static int countWithPrefix(String prefix) {
        Node n = walk(prefix);
        return n == null ? 0 : n.passCount;
    }

    static String longestCommonPrefix() {
        StringBuilder sb = new StringBuilder();
        Node n = root;
        while (n.children.size() == 1 && !n.isWord) {   // a single path and no word ends here
            Map.Entry<Character, Node> only = n.children.entrySet().iterator().next();
            sb.append(only.getKey());
            n = only.getValue();
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        for (String w : new String[]{"interview", "internet", "interval", "internal"}) insert(w);
        System.out.println("longest common prefix: " + longestCommonPrefix());
        for (String w : new String[]{"inter", "intern", "interv", "intra"}) {
            System.out.println("startsWith(" + w + ") = " + startsWith(w) + ", words with this prefix: " + countWithPrefix(w));
        }
        insert("in");
        System.out.println("after inserting \"in\": longest common prefix = " + longestCommonPrefix());
    }
}

