import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Autocomplete {
    static class Node {
        Map<Character, Node> children = new TreeMap<>();
        int frequency;                          // > 0 means a stored word
    }

    record Suggestion(String word, int frequency) {}

    static Node root = new Node();

    static void add(String word, int frequency) {
        Node n = root;
        for (char c : word.toCharArray()) n = n.children.computeIfAbsent(c, k -> new Node());
        n.frequency = frequency;
    }

    static void dfs(Node n, StringBuilder path, List<Suggestion> out) {
        if (n.frequency > 0) out.add(new Suggestion(path.toString(), n.frequency));
        for (Map.Entry<Character, Node> e : n.children.entrySet()) {
            path.append(e.getKey());
            dfs(e.getValue(), path, out);
            path.deleteCharAt(path.length() - 1);
        }
    }

    static List<String> suggest(String prefix, int limit) {
        Node n = root;
        for (char c : prefix.toCharArray()) {
            n = n.children.get(c);
            if (n == null) return List.of();    // nothing starts with this prefix
        }
        List<Suggestion> found = new ArrayList<>();
        dfs(n, new StringBuilder(prefix), found);   // only the prefix's subtree
        found.sort(Comparator.comparingInt(Suggestion::frequency).reversed().thenComparing(Suggestion::word));
        List<String> top = new ArrayList<>();
        for (int i = 0; i < Math.min(limit, found.size()); i++) top.add(found.get(i).word());
        return top;
    }

    public static void main(String[] args) {
        String[] words = {"camera", "camp", "camping", "campus", "can", "candle", "cat", "car", "cart"};
        int[] freq = {40, 25, 90, 30, 70, 15, 85, 60, 20};
        for (int i = 0; i < words.length; i++) add(words[i], freq[i]);
        for (String typed : new String[]{"c", "ca", "cam", "camp", "cant"}) {
            System.out.println("typed \"" + typed + "\" -> " + suggest(typed, 3));
        }
    }
}

